function kGet(t,tf){if(lsec(tf)&&solLocal(t))return kGetLocal(t,tf);if(tf==='5s'||tf==='15s')tf='1s';const k=kKey(t,tf);let e=KC.get(k);const fresh=tf==='1s'?MS_3000:tf==='1m'?MS_8000:MS_20000;if(!e){e={at:0,bars:[],busy:0,src:'',err:''};KC.set(k,e)}if(!e.busy&&Date.now()-e.at>fresh&&R){e.busy=1;R.klineHist(NETOF[t.chain],t.c,t.pool||'',KTF[tf]||'5m',0,true).then(r=>{const B=Array.isArray(r?.bars)?r.bars:Array.isArray(r)?r:[];e.bars=B.filter(b=>b&&b.t>0&&b.c>0).map(b=>({t:Math.floor(b.t/MS_1000),o:+b.o,h:+b.h,l:+b.l,c:+b.c,v:+b.v||0,gap:b.gap?1:0}));e.src=r?.src||'';if(r?.pool&&!t.pool)t.pool=r.pool;e.err=B.length?'':(r?.err||(r&&!r.src?L('K 线来源这一分钟的次数用完（GeckoTerminal 共用限速），稍后自动再拿','Candle source rate-limited; retrying shortly'):''));if(r?.sup>0&&!t.sup)t.sup=r.sup;const lb=e.bars.at(-1);if(lb&&!(t.p>0))t.p=lb.c;for(const h of CHARTS)h.update()}).catch(er=>{e.err=String(er?.message||er).slice(0,60)}).finally(()=>{e.busy=0;e.at=Date.now()})}return e}
