function setFocus(t){if(!t)return;ST.focus=t.id;for(const [,x] of INST){const T=PT[x.p.t];if(T.widget){paintHead(x);x.h.retarget&&x.h.retarget()}x.h.mark&&x.h.mark()}DRW.h&&DRW.h.mark&&DRW.h.mark()}
