function openTok(t,fromHash){if(!t)return;const t0=performance.now();$$(`.lr[data-t="${CSS.escape(t.id)}"],.cd[data-t="${CSS.escape(t.id)}"]`).forEach(r=>r.classList.add('sel'));busy(1);markNav('openTokFeedback',t0);defer(()=>{openTokNow(t,fromHash,t0);busy(0)})}
