function dataHealth(){const V=SRC.v||{};const rows=[];for(const ch of CHS){const a=LOAD.at[ch];rows.push(`<div class="bline"><span>${CH[ch].name}</span><b class="${LOAD.err[ch]?'dn':a?'up':'t3'}">${LOAD.err[ch]?esc(LOAD.err[ch]):a?L(`看盘 ${TOK[ch].length} 个币 · ${Math.round((Date.now()-a)/MS_1000)} 秒前`,`${TOK[ch].length} tokens · ${Math.round((Date.now()-a)/MS_1000)}s ago`):L('还没读','Not loaded')}${latOf(ch)!=null?' · '+L('KOL 动态中位','KOL median')+' '+latOf(ch)+L(' 秒','s'):''}</b></div>`)}
 const rpc=V.rpc||{};const rp=Object.entries(rpc).map(([k2,x])=>`<div class="bline"><span>RPC ${esc(k2)}</span><b class="t2">${(x.nodes||[]).filter(n=>n.ok).length}/${(x.nodes||[]).length} ${L('个节点通','nodes ok')}</b></div>`).join('');
 return rows.join('')+rp+`<div class="bline"><span>${L('AVE 讯号／板块','AVE signals / sectors')}</span><b class="${AVEQ.err.sig||AVEQ.err.topics?'wn':'up'}">${AVEQ.err.sig==='relay'||AVEQ.err.topics==='relay'?aveNeedTxt():AVEQ.err.sig||AVEQ.err.topics||L('正常','OK')}</b></div>${UNK.map(u=>`<div class="bline"><span>${u.kind==='okx'?L('OKX AI 钱包','OKX AI wallet'):L('币安 AI 钱包','Binance AI wallet')} · ${esc(u.name||u.id)}（${esc(u.id)}）</span><b class="wn">${L('钱包新支援，等雷达更新才会开放买卖','New wallet chain — trading opens after a radar update')}</b></div>`).join('')}<div style="margin-top:8px">${legBtn('more','节点设定、实时日志（旧设定页）','Nodes & live log','radio')}</div>`}
