/* RV8-11 旧策略页的段落是画完之后才出现、有的收在折叠里：最多等几次，找到就展开折叠再卷过去（找不到就写原因） */
function legScrollTo(re,n=0){const M=document.querySelector('body>main');const el=M&&[...M.querySelectorAll('.page.on *')].find(x=>x.children.length===0&&re.test(x.textContent||''));if(!el){if(n<CNT_12)setTimeout(()=>legScrollTo(re,n+1),MS_1000/4);else toast(L('旧策略页里找不到「各链发射台自动买」这一段','Section not found on the strategy page'));return}let p=el;while(p&&p!==M){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement}el.scrollIntoView({block:'start'});const blk=el.closest('.box,.card,section,div');if(blk){blk.style.outline='2px solid #f0b90b';setTimeout(()=>{blk.style.outline=''},MS_3000)}}
function pageX(e){const nw=e.target.closest('.nwr[data-url]');if(nw){try{R.open(nw.dataset.url)}catch{}return}const lg=e.target.closest('[data-leg]');if(lg){const [p,sub]=lg.dataset.leg.split('@');legShow(p,sub==='ai'?()=>{document.querySelector('#segK a[data-sk="ai"]')?.click()}:sub==='mca'?()=>legScrollTo(/发射台自动买|Launchpad auto-?buy/i):null);return}}
function wireNav(){$('#pg').addEventListener('click',pageX);$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-nv]');if(b)navGo(b.dataset.nv)});$('#navv').addEventListener('click',()=>ROOTEL.classList.remove('navOpen'))}

