let TICK=0;
async function searchAddr(v){v=String(v||'').trim();const evm=/^0x[0-9a-fA-F]{40}$/.test(v),b58=/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(v);if(!evm&&!b58)return null;const hit=[...BYID.values()].find(x=>x.c.toLowerCase()===v.toLowerCase());if(hit)return hit;
 const order=b58?['sol']:[ST.chain,...CHS.filter(c=>c!==ST.chain&&c!=='sol')].filter(c=>c!=='sol');for(const ch of order){try{const d=isOwnTrade(ch)?await R.tokenQuick(NETOF[ch],v):await R.mc('detail',{chain:NETOF[ch],c:v});const P=d?.pair||{};const tk=d?.tok||{};const sym=P.base?.symbol||tk.sym;if(sym||P.price||tk.price){const t=stubTok(ch,v,{sym,mc:num(P.mcap??P.fdv??tk.mc)});if(t){t.n=P.base?.name||tk.name||t.n;dApply(t,d);return t}}}catch{}}return null}
const MONLAST=new Map();
function monCheck(){if(!MONP.size)return;for(const t of TOK[ST.chain]){const prev=MONLAST.get(t.id);MONLAST.set(t.id,{l:t.l,c5:t.ch.m5});for(const [pid,o] of MONP){const pv=parseFloat(o.pump),lv=parseFloat(o.liq);if(isFinite(pv)&&t.ch.m5!=null&&t.ch.m5>=pv&&!(prev&&prev.c5!=null&&prev.c5>=pv)){const m={id:'m'+Math.random().toString(36).slice(2),tk:t.id,k:'pump',v:t.ch.m5,ts:nowS(),o:pid};FEED.mon.unshift(m);pushFeed('monitor',m)}if(isFinite(lv)&&prev&&prev.l!=null&&t.l!=null&&t.l-prev.l>=lv){const m={id:'m'+Math.random().toString(36).slice(2),tk:t.id,k:'liq',v:t.l-prev.l,ts:nowS(),o:pid};FEED.mon.unshift(m);pushFeed('monitor',m)}}}if(FEED.mon.length>CNT_200)FEED.mon.length=200}
function alertCheck(){for(const x of ALERTS){if(!x.on||x.hit)continue;const t=BYID.get(x.tk);if(!t||!(t.mc>0))continue;if(x.k==='ge'?t.mc>=x.v:t.mc<=x.v){x.hit=Date.now();LS.s('alerts2',ALERTS);const msg=`${t.s} ${x.k==='ge'?'≥':'≤'} ${fU(x.v)}（${L('现在','now')} ${fU(t.mc)}）`;toast(I('bell','s12')+' '+esc(msg));try{new Notification(L('罗宾猫雷达 · 价格提醒','RobinCat Radar · price alert'),{body:msg})}catch{}redrawType('alerts')}}}
let OTH=0;async function tick(){TICK++;if(!TV.on)return;
 const S=__tvO.snap();const es=!!(S&&S.set&&S.set.estop);if(es!==!!ST.estop){ST.estop=es?1:0;paintTop()}
 await loadChain(ST.chain);if(TICK%UI_24===0){const o=CHS.filter(c=>c!==ST.chain);loadChain(o[OTH++%o.length])}
 if(TICK%CNT_4===1)loadKol();if(TICK%CNT_4===UI_3)loadCalls();if(TICK%UI_6===0)loadPx();if(TICK%UI_10===UI_5)loadSrc();if(TICK%UI_3===0)riskVisible();if(TICK%UI_40===UI_7)loadModes();if(TICK%UI_2===0)loadPos();
 monCheck();alertCheck();
 const onTok=ROOTEL.classList.contains('rt-tok');const mob=matchMedia('(max-width:760px)').matches;
 const onPg=ROOTEL.classList.contains('rt-pg');if(!onTok&&!onPg)for(const [id,x] of INST){if(mob&&id!==MON)continue;if(x.el.offsetParent===null)continue;x.h.update&&x.h.update()}
 if(DRW.t&&DRW.h)DRW.h.update&&DRW.h.update();
 if(onPg)for(const h of PGH)h.update&&h.update();
 if(onTok&&TKP.t){const t=TKP.t;dGet(t);trGet(t);const H=$('#tkH');const q=H._q&&H._q.t===t?H._q:(H._q={t,mc:$('[data-k=mc]',H),p:$('[data-k=p]',H),ch:$('[data-k=ch]',H),v:$('[data-k=v]',H),h:$('[data-k=h]',H)});if(t.mc!=null)setN(q.mc,t.mc,fU,true);q.p.textContent=fP(t.p);q.ch.textContent=fPct(t.ch.h24);q.ch.className=cls(t.ch.h24);q.v.textContent=fU(t.vol.h24);q.h.textContent=fN(t.h);TKP.chart.update();if(TICK%CNT_2===0)TKP.list.update()}
 for(const m of MAJ){for(const el of $$(`[data-mx="${m[0]}"]`))el.textContent=m[1]!=null?'$'+m[1].toLocaleString('en-US',{maximumFractionDigits:m[1]>SEC_1000?0:2,minimumFractionDigits:m[1]>MS_1000?0:2}):'—'}
 const lat=$('#lat');if(lat){const a=LOAD.at[ST.chain];lat.textContent=a?L(`${Math.max(0,Math.round((Date.now()-a)/MS_1000))} 秒前`,`${Math.max(0,Math.round((Date.now()-a)/MS_1000))}s ago`):''}
 const err=!!LOAD.err[ST.chain]&&!TOK[ST.chain].length;if(err!==!!ST.err){ST.err=err?1:0;paintDock()}
 if(TICK%UI_3===0&&!onTok)paintTick()}
function paintDockBadges(){for(const k of ['calls','kolfeed']){const b=$(`.dk[data-dk=${k}]`);if(!b)continue;let s=$('.bdg',b);const n=DRW.badge[k];if(!n){s&&s.remove();continue}if(!s){s=document.createElement('span');s.className='bdg';b.appendChild(s)}s.textContent=n}}

/* ===== 首次使用导览：4 步，Esc／略过可关，设定页可重看 ===== */
const TOUR=[['#chb',['先选链','Pick a chain'],['十条链。能不能下单照你的钱包回报（BNB Chain、Robinhood 一定可以）；不能的链标「只看」。','Ten chains. Trading follows what your wallet supports (BNB Chain & Robinhood always); others are view-only.']],['#mkt',['大盘一眼看完','Market at a glance'],['主流币、涨跌家数、成交、最热板块。','Majors, breadth, volume, hottest sector.']],['#ws .pnl',['工作区面板','Workspace panels'],['排行、板块、讯号、KOL 动态、喊单、新币……都能拖拉、放大、换种类、存成布局。','Drag, resize, switch type, save layouts.']],['.estop',['紧急全停','Emergency stop'],['每一页都在。按下去所有自动买卖立刻停；解除只能在设定按「重新设定」。','On every page. Halts all automation; clear only in Settings.']]];
function startTour(force){if(!force&&LS.g('tour',0))return;let i=0;const ov=document.createElement('div');ov.className='tour';ROOTEL.appendChild(ov);
 const end=()=>{ov.remove();LS.s('tour',1);removeEventListener('keydown',kd,true)};const kd=e=>{if(e.key==='Escape'){e.stopPropagation();end()}};addEventListener('keydown',kd,true);
 const show=()=>{let el=null;for(const s of [TOUR[i][0]]){el=$$(s).find(x=>x.offsetParent)}const r=el?el.getBoundingClientRect():{left:innerWidth/2-60,top:innerHeight/2-20,width:PX_120,height:PX_40,bottom:innerHeight/2+20,right:innerWidth/2+60};
  const bw=Math.min(300,innerWidth-24);let x=clamp(r.left,12,innerWidth-bw-12),y=r.bottom+12;if(y+PX_170>innerHeight)y=Math.max(12,r.top-182);
  ov.innerHTML=`<div class="thl" style="left:${r.left-4}px;top:${r.top-4}px;width:${r.width+8}px;height:${r.height+8}px"></div><div class="tbx" style="left:${x}px;top:${y}px;width:${bw}px"><small class="t3">${i+1} / ${TOUR.length}</small><b>${L(...TOUR[i][1])}</b><p>${L(...TOUR[i][2])}</p><div class="btns"><button class="btn s" data-tk="skip">${L('略过','Skip')}</button><button class="btn p" data-tk="next">${i<TOUR.length-1?L('下一步','Next'):L('开始用','Done')}</button></div></div>`};
 ov.addEventListener('click',e=>{const b=e.target.closest('[data-tk]');if(!b)return;if(b.dataset.tk==='skip'||i>=TOUR.length-1){end();return}i++;show()});show()}

