function boot(){const t0=performance.now();
 TV.lang=ST.lang==='en'?'en':'zh-CN';applyTheme();paintTop();paintWbar();paintDock();paintNav();wireNav();wireTop();wireDock();wireWS();renderWS();
 loadModes();loadChain(ST.chain,true).then(()=>{for(const [,x] of INST)x.h.redraw&&x.h.redraw()});CHS.filter(c=>c!==ST.chain).forEach((c,i)=>setTimeout(()=>loadChain(c,true),1500*(i+1)));loadPx();loadKol();loadCalls();loadPos();
 setInterval(()=>{if(!document.hidden)tick().catch(e=>console.error(e))},2500);route(true);if(ST.zoom&&ST.zoom!==UI_100)tvZoom(ST.zoom);if(!/[?&]notour/.test(location.search)&&TV.on)setTimeout(()=>startTour(),1500);
 document.addEventListener('radar-lang',()=>{const l=__tvO.lang();if(l!==ST.lang){ST.lang=l;rerenderAll()}});PERF.boot=+(performance.now()-t0).toFixed(1)}
boot();

